static void check(bool b,const char* s){if(!b)throw std::runtime_error(s);}static QStringList ids(QJsonObject r){QStringList out;for(auto v:r.value("patterns").toArray())out<<v.toObject().value("id").toString();out.sort();return out;}
int main(int argc,char**argv){QApplication app(argc,argv);try{check(argc>1,"fixture path required");QFile f(QString::fromLocal8Bit(argv[1]));check(f.open(QIODevice::ReadOnly),"fixture read");auto cases=QJsonDocument::fromJson(f.readAll()).object().value("cases").toArray();QJsonArray snapshots;for(auto v:cases){auto c=v.toObject(),s=c.value("snapshot").toObject(),r=auctionAnalysis::analyze(s);QStringList expected;for(auto x:c.value("expected").toArray())expected<<x.toString();check(ids(r)==expected,"actual old eight formula parity");check(r.value("historyCount").toInt()==20&&r.value("coverageRatio").toDouble()==1&&r.value("expectedMissingDates").toArray().size()==1,"history and supplied calendar coverage");check(std::abs(r.value("thresholds").toObject().value("priceMovePercent60s").toDouble()-c.value("thresholds").toObject().value("priceMovePercent60s").toDouble())<1e-10,"threshold parity");snapshots.append(s);}auto source=snapshots[0].toObject(),original=auctionAnalysis::analyze(source);auto input=source.value("input").toObject();auto meta=input.value("meta").toObject();meta["auctionFieldContractVerified"]=false;input["meta"]=meta;auto ordinary=source;ordinary["input"]=input;check(auctionAnalysis::analyze(ordinary).value("dataLevel")=="D0","ordinary quote never auction shapes");input=source.value("input").toObject();auto history=input.value("history").toArray();auto h=history[0].toObject();h.remove("instrumentId");history[0]=h;input["history"]=history;auto missingId=source;missingId["input"]=input;check(auctionAnalysis::analyze(missingId).value("patternStatus")=="insufficient-history","missing full history identity excludes");input=source.value("input").toObject();history=input.value("history").toArray();h=history[0].toObject();h["matchedAmount"]=999999;history.append(h);input["history"]=history;auto conflict=source;conflict["input"]=input;check(auctionAnalysis::analyze(conflict).value("historyCount").toInt()==19,"conflicting duplicate date not arbitrary first");input=source.value("input").toObject();auto points=input.value("rows").toArray();auto future=points.last().toObject();auto t=QDateTime::fromString(future.value("time").toString(),Qt::ISODate).addSecs(5);future["time"]=t.toString(Qt::ISODate);future["availableAt"]=t.toString(Qt::ISODate);future["auctionReferencePrice"]=1000;points.append(future);input["rows"]=points;auto later=source;later["input"]=input;auto ignored=auctionAnalysis::analyze(later);check(ids(ignored)==ids(original)&&ignored.value("points").toArray().size()==13,"future point doesn't change historical result");input=source.value("input").toObject();meta=input.value("meta").toObject();meta.remove("auctionExpectedIntervalMs");input["meta"]=meta;auto noCadence=source;noCadence["input"]=input;check(auctionAnalysis::analyze(noCadence).value("coverageRatio").isNull(),"no inferred cadence");input=source.value("input").toObject();points=input.value("rows").toArray();auto bad=points[0].toObject();bad["instrumentId"]="SZ:stock:000001";points[0]=bad;input["rows"]=points;auto mixed=source;mixed["input"]=input;check(auctionAnalysis::analyze(mixed).value("dataLevel")=="D0","point identity conflict refused");auto absentCalendar=source;absentCalendar.remove("coverage");check(auctionAnalysis::analyze(absentCalendar).value("expectedMissingDates").isNull(),"calendar missing not zero gaps");auto insufficient=source;auto shortInput=source.value("input").toObject();auto shortRows=shortInput.value("rows").toArray();for(int i=0;i<4;i++)shortRows.removeAt(4);shortInput["rows"]=shortRows;insufficient["input"]=shortInput;check(auctionAnalysis::analyze(insufficient).value("patternStatus")=="insufficient-data","process missing bins cannot pass coverage");auto duplicatePoint=source;auto dpInput=source.value("input").toObject();auto dpRows=dpInput.value("rows").toArray();auto dp=dpRows[0].toObject();dp["auctionReferencePrice"]=11;dpRows.append(dp);dpInput["rows"]=dpRows;duplicatePoint["input"]=dpInput;check(auctionAnalysis::analyze(duplicatePoint).value("dataLevel")=="D0","native same time/revision conflict preserved");auto widget=auctionAnalysisPage(nullptr,[=]{return snapshots;});auto list=widget->findChild<QListWidget*>("auctionAnalysisSnapshots");check(list->count()==8,"actual existing snapshot UI");list->setCurrentRow(0);for(auto b:widget->findChildren<QPushButton*>())if(b->text()=="分析所选本机快照")b->click();check(widget->findChild<QListWidget*>("auctionAnalysisRows")->count()==13,"actual original point ledger");for(auto b:widget->findChildren<QPushButton*>())if(b->text()=="完整缺口/阈值/原始输入")b->click();check(widget->findChild<QPlainTextEdit*>("auctionAnalysisReader")->toPlainText().contains("historyAudit"),"complete native reader");auto state=auctionAnalysisSaveState(widget);auto reopened=auctionAnalysisPage(nullptr,[=]{return snapshots;});auctionAnalysisRestoreState(reopened,state);check(auctionAnalysisSaveState(reopened).value("view").toInt()==2&&auctionAnalysisBack(reopened)&&auctionAnalysisBack(reopened)&&!auctionAnalysisBack(reopened),"recreation/internal back");delete widget;delete reopened;std::cout<<"PASS auction eight actual JS formula/strict fullID/known cadence/calendar/conflict/future/ordinary distinction/native snapshot-point-reader-recreation; staging only\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
